"""docs/REAL_DATA_FINDINGS.md generator. Every number comes from reports/real_data.json (written by scripts/validate_real.py)."""
from __future__ import annotations

from datetime import datetime, timezone

from scripts.make_results import load, table


def real_md() -> str:
    d = load("real_data.json")
    if not d:
        return "# Real-data findings\n\nNo real-data run yet. Run `python scripts/load_flaws.py` and `python scripts/validate_real.py`.\n"
    now = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    md = ["# Real-data findings\n",
          f"> Generated by `scripts/make_results.py` on {now} from `reports/real_data.json` (produced by `scripts/validate_real.py`). Do not edit by hand.\n",
          "Everything else in this project was measured on synthetic data written by the same author as the detectors. This page is the first contact with logs the project did not generate.\n"]
    src = d["sources"]
    md += ["## 1. Sources and integrity\n",
           f"- **Stratus Red Team technique samples, Invictus-IR (32 Stratus attacks), SANS-504 S3 ransomware lab:** `{src['samples_repo']}` at commit `{d.get('samples_commit') or 'n/a'}`.",
           f"- **flaws.cloud CloudTrail (Scott Piper / Summit Route):** `{src['flaws_tar']}` (write-up: {src['flaws_blog']}). IP addresses and account IDs are anonymized by the publisher."]
    ig = d.get("flaws_integrity")
    if ig:
        md.append(f"- The original tarball ({ig['tar_bytes']:,} bytes, {ig['members']} members) is byte-identical to the copy in the samples repository for {ig['identical_to_repo_copy']}/{ig['members']} members (SHA-256).")
    md += ["- The synthetic geolocation registry is **disabled** for all real data: it is made up, and applying it to real or anonymized IPs would invent countries and impossible-travel alerts. "
           "Geo-based signals are therefore silent here by design.\n"]

    st = d["stratus"]
    b, a = st["before"], st["after"]
    md += ["## 2. Stratus Red Team: rule coverage per technique\n",
           "Each file is a real CloudTrail capture of one Stratus Red Team technique detonation (duplicate aliases counted once). *Technique-specific coverage* means at least one rule "
           "other than the two generic ones (user agent, AccessDenied burst) fired on the technique's own events.\n"]
    if b:
        md += [table(["", "Rules", "Techniques", "Technique-specific hit", "Any hit"],
                     [[f"**Before** (measured at commit `{b['measured_at_commit'].split()[0]}`, rules written without seeing real data)", b["rules_evaluated"], b["techniques"],
                       f"{b['covered_specific']}/{b['techniques']} ({b['covered_specific']/b['techniques']*100:.0f}%)", f"{b['covered_any']}/{b['techniques']}"],
                      ["**After** (post-hoc, see caveat)", a["rules_evaluated"], a["techniques"], f"{a['covered_specific']}/{a['techniques']} ({a['covered_specific']/a['techniques']*100:.0f}%)",
                       f"{a['covered_any']}/{a['techniques']}"]], ["l", "r", "r", "r", "r"]), ""]
    md += ["**What changed.** Two shipped rules had real bugs that synthetic data could not reveal: R017 (security group open to the world) understood one request shape and missed real records "
           "(top-level `cidrIp`, a `/0` mask that the anonymizer wrote with a random address, IPv6 `::/0`, and the response's rule set), and R009 (role trust policy opened to an external account) "
           "ignored `CreateRole`'s `assumeRolePolicyDocument` field. Seventeen new rules (R025-R041) were then added for techniques with no coverage. "
           "**That new coverage is post-hoc: those rules were written after looking at these very samples, so it is a regression check, not an independent measurement.** "
           "The honest real-data number is the *before* row.\n"]
    md += ["Note on credit: a hit means a rule fired on one of the technique's own events, not that the rule *recognizes the technique*. For example `ec2-steal-instance-credentials` is credited to R032, "
           "which flags the SSM `SendCommand` used to read the instance metadata service; nothing here detects the credential theft itself.\n"]
    unc = [r for r in st["rows"] if not r["after_specific"]]
    if unc:
        md.append("Still not covered: " + "; ".join(f"`{r['technique']}` ({', '.join(r['event_names'])})" for r in unc) +
                  ". These are Lambda code or configuration overwrites, which are indistinguishable from ordinary deployments without per-function baselines, so no rule was added.\n")
    md += [table(["Tactic", "Technique", "Events", "Before", "After"],
                 [[r["tactic"].replace("_", " "), r["technique"].replace("aws.", ""), r["events"],
                   "-" if r["before"] is None else (", ".join(sorted(r["before"])) or "miss"), ", ".join(sorted(r["after"])) or "miss"] for r in st["rows"]], ["l", "l", "r", "l", "l"]), ""]

    for key, title, num in (("invictus", "Invictus-IR: 32 Stratus attacks in one account", 3), ("sans", "SANS-504 S3 ransomware lab", 4)):
        x = d.get(key)
        if not x:
            continue
        o = x["overview"]
        md += [f"## {num}. {title}\n",
               f"{o['events']:,} unique events ({x['ingest']['records_seen']:,} records read, {x['ingest']['duplicates']:,} exact duplicates dropped), {o['identities']} identities, "
               f"{o['first']} → {o['last']}. Rules produced **{x['alerts']} alerts** covering {x['alerted_events']:,} events (the dataset's most common region, `{x['home_region_assumed']}`, is treated as home).\n",
               table(["Rule", "Title", "Severity", "Alerts", "Identities", "Top identity"],
                     [[r["rule_id"], r["title"], r["severity"], r["alerts"], r["identities"], r["top_identity"]] for r in x["rules"][:14]], ["l", "l", "l", "r", "r", "l"]), ""]
        if x["high_risk_gap"]:
            md += ["High-risk APIs seen but **not** alerted (candidate gaps, or benign activity):\n",
                   table(["API", "Events", "Alerted"], [[g["event_name"], g["events"], g["alerted"]] for g in x["high_risk_gap"]], ["l", "r", "r"]), ""]
        if key == "sans":
            md += ["Reading it: most `PutObject` volume in this lab is S3/CloudTrail service delivery (an `AWSService` identity), not the attacker. The attacker activity is a root principal and an IAM user "
                   "performing a burst of object reads (caught by R024) plus root usage (R018, deduplicated to one alert per root IP per hour after the first run of this lab produced one alert "
                   "per root event). The ransomware-style re-encryption itself is not visible as management events in this export, so nothing here detects it directly.\n"]

    f = d.get("flaws")
    if f:
        o, g2 = f["overview"], f.get("ingest") or {}
        dup = (f" ({g2['records_seen']:,} records read; **{g2['duplicates']:,} ({g2['duplicates']/g2['records_seen']*100:.0f}%) were exact duplicates by eventID and were dropped**, "
               "so the commonly quoted figure of about 1.9M is records, not unique events)") if g2 else ""
        md += ["## 5. flaws.cloud: about 1.2 million real events from real attackers\n",
               f"{o['events']:,} unique events{dup}, {o['identities']} identities, {o['source_ips']:,} source IPs, {o['first'][:10]} → {o['last'][:10]}. "
               "There are no labels, so this section is qualitative apart from the one independent check below.\n",
               "Top identities: " + ", ".join(f"`{i}` ({n:,})" for i, n in o["top_identities"][:5]) + ". Top events: " + ", ".join(f"`{e}` ({n:,})" for e, n in o["top_events"][:5]) + ".\n",
               f"### 5a. Rules over the whole timeline ({f['rules']['alerts']:,} alerts)\n",
               "Home region assumed to be `us-west-2` (where the training site is hosted); this affects R016 only.\n",
               (f"**Deduplication matters on real traffic:** with it off, the same rules over the same events produce {f['rules']['alerts_without_dedupe']:,} alerts "
                f"({f['rules']['alerts_without_dedupe']/max(f['rules']['alerts'], 1):.0f}× more than the {f['rules']['alerts']:,} shown below), because one automated burst repeats the same call hundreds of thousands of times. "
                "Repeats within five minutes for the same rule, identity and source IP are folded into one alert that still lists every matched event.\n") if f["rules"].get("alerts_without_dedupe") else "",
               table(["Rule", "Title", "Sev", "Alerts", "Identities", "Top identity", "First", "Last"],
                     [[r["rule_id"], r["title"], r["severity"], f"{r['alerts']:,}", r["identities"], r["top_identity"], r["first"][:10], r["last"][:10]] for r in f["rules"]["by_rule"][:16]],
                     ["l", "l", "l", "r", "r", "l", "l", "l"]), ""]
        sg = f.get("surge")
        if sg:
            md += [f"### 5b. An independent check: the {sg['month']} volume surge\n",
                   f"Found from raw monthly counts only (no labels): **{sg['events_in_month']:,} events in {sg['month']}, {sg['x_median']}× the median month ({f['monthly_median_events']:,.0f})**, dominated by "
                   f"`{sg['dominant_identity']}` calling `{sg['dominant_event']}` ({sg['dominant_events']:,} calls across {sg['regions_touched']} regions), "
                   f"starting {sg['onset']}. {sg['errors_share']*100:.0f}% of those calls returned an error, so this is a burst of automated-looking instance-launch attempts across regions that were being "
                   "refused, not successful abuse. The identities are named after the flaws.cloud challenge levels (`Level6`, `backup`), the IAM users that the challenge hands to players, "
                   "so this is activity by players or scripts using those credentials (an inference from the names, not something the logs prove).\n"]
            ml = f.get("ml")
            if ml:
                md += [f"The anomaly model was trained **only on the history before the surge** ({ml['train_period']}, {ml['training_windows']:,} windows), with the threshold calibrated to about "
                       f"{ml['calibration_fp_per_day_target']} flagged windows/day on the last 15% of that history, then run over {ml['scored_period']} ({ml['scored_days']} days, "
                       f"{ml['scored_windows']:,} windows, {ml['flagged_windows']:,} flagged).\n",
                       table(["Layer", "Alerts", "Incidents", "Incidents/day", "Surge events covered", "Surge detected", "Onset → first alert (min)"],
                             [[k, v["alerts"], v["incidents"], v["incidents_per_day"], f"{v['surge_events_covered']:,} ({v['surge_events_covered_pct']}%)", "yes" if v["surge_detected"] else "no",
                               v["minutes_from_onset_to_first_alert"] if v["minutes_from_onset_to_first_alert"] is not None else "n/a"] for k, v in ml["by_layer"].items()],
                             ["l", "r", "r", "r", "r", "l", "r"]), ""]
                if ml["top_incidents"]:
                    md += ["### 5c. Highest-risk incidents in the scored period (combined layers)\n",
                           table(["Severity", "Risk", "Identities", "First seen", "Tactics", "Layers", "Alerts"],
                                 [[i["severity"], f"{i['risk']:.0f}", ", ".join(i["identities"]), i["first_seen"][:16], " → ".join(i["tactics"]) or "n/a", ", ".join(i["sources"]), i["alerts"]]
                                  for i in ml["top_incidents"]], ["l", "r", "l", "l", "l", "l", "r"]), ""]
                rate = ml["flagged_windows"] / max(ml["scored_days"], 1)
                rx = load("recalibration_experiment.json")
                md += [f"The model flagged {ml['flagged_windows']:,} windows over {ml['scored_days']} days (**{rate:.1f}/day**) against the {ml['calibration_fp_per_day_target']}/day it was calibrated to on the "
                       "last stretch of its own history. That headline overstates the problem: most of those windows are the genuine surge month itself."]
                if rx:
                    st = rx["threshold_strategies"]["static (calibrated once)"]
                    g = rx["threshold_strategies"]["trailing quantile + storm guard"]
                    md[-1] += (f" Outside the surge month the rate is **{st['outside_per_day']}/day** ({st['outside_flagged']} windows over {rx['days_outside_surge']} days; {st['surge_month_flagged']:,} fall in the surge month). "
                               f"Window scores do drift upward (median {rx['calibration_median_score']} at calibration vs {rx['baseline_strategies']['frozen baseline']['median_window_score']} later) because the per-identity baseline goes stale, "
                               f"but I tried five recalibration strategies (`scripts/recalibration_experiment.py`) and none helps much: the best, a trailing-quantile threshold with a storm guard, gives {g['outside_per_day']}/day "
                               f"(-{round((1 - g['outside_per_day'] / st['outside_per_day']) * 100)}%) while keeping {round(g['surge_month_flagged'] / st['surge_month_flagged'] * 100)}% of the surge detections; a median+MAD threshold is worse "
                               f"({rx['threshold_strategies']['median + k*MAD, trailing 30d']['outside_per_day']}/day), and an unguarded trailing quantile adapts to the surge and masks it. "
                               "The remaining flagged windows are mostly unusual-but-benign inventory sweeps, not drift. Adaptive thresholding therefore ships as an optional, off-by-default library (`src/detection/calibration.py`).")
                md[-1] += "\n"
                if ml["top_anomalies_outside_surge"]:
                    breadth = ("log_n", "n_distinct_names", "volume_z", "n_services", "log_n_ips")
                    sweep = sum(1 for a in ml["top_anomalies_outside_surge"] if any(a["reasons"].startswith(b) for b in breadth))
                    md += [f"### 5d. Strongest anomaly windows outside the surge month ({ml['flagged_windows_in_surge_month']} flagged windows fell inside it)\n",
                           f"{sweep} of the top {len(ml['top_anomalies_outside_surge'])} are led by volume/breadth features (`log_n`, `n_distinct_names`, `volume_z`, `n_services`), i.e. large inventory-style sweeps by one identity "
                           "rather than rare actions. Unusual, but not necessarily malicious: this is the typical false-positive type for this layer.\n",
                           table(["Identity", "When", "Score", "Events in window", "Why (top SHAP reasons)"],
                                 [[a["identity"], a["when"][:16], a["score"], a["events_in_window"], a["reasons"]] for a in ml["top_anomalies_outside_surge"]], ["l", "l", "r", "r", "l"]), ""]
        md += ["### 5e. Reading the flaws.cloud numbers\n",
               "- This is **unsupervised**, and the 'normal' history already contains attackers and learners poking at the site, so 'unusual' means unusual relative to that history, not to a clean baseline.",
               "- Real IPs are anonymized and the geo registry is off, so travel, country and ASN signals contribute nothing; the IP layer can only see shared-IP and many-IP patterns.",
               "- The surge check is a sanity check on one event visible in raw counts. It is not a recall measurement, and one detected surge says little about the next attack.",
               "- Rule hit counts are alerts, not confirmed attacks: many identities in this dataset are legitimate or are learners, so counts overstate malicious activity.\n"]

    md += ["## 6. What real data taught\n",
           "1. **Synthetic recall does not transfer.** The rules caught everything the generator produced and a minority of real techniques; the difference is the generator author's blind spots, which is why this check exists.",
           "2. **Schema fidelity matters.** Two shipped rules were wrong on real record shapes. Real exports also contain top-level JSON arrays, missing fields, `AWSAccount` identities, IPv6 and empty "
           "source IPs, anonymized fake regions and leading-zero IPs; fuzz tests now cover these and the ingestor handles them.",
           "3. **Alert floods.** Per-event rules flooded on real bursts (root usage on the SANS lab; instance launches on flaws.cloud). The engine now folds repeats per rule, identity and source IP "
           "within five minutes into one alert, and root usage is deduplicated per IP per hour.",
           "3b. **AWS service principals look like attackers to naive rules.** On the SANS lab the AccessDenied-burst rule (R023) fired 164 times on `delivery.logs.amazonaws.com`, an AWS service "
           "delivering logs. Service principals are now excluded from that rule.",
           "4. **Identity type is not a reliable human/service signal.** Many Stratus steps run as an assumed role, so rules that exclude `AssumedRole` to avoid service noise would miss an attacker "
           "holding stolen role credentials. That trade-off is deliberate and visible in R024 and R030.",
           "5. **Duplicates are common in real exports** and must be dropped by `eventID`.\n"]
    return "\n".join(md)
